mapper.insert:
INSERT INTO lsc_data_analy.order_summary_day (`date`, `order_num`, `product_num`, `price`, `avg_price`, `shop_id`, `deleted`) SELECT o.d, o.order_num, COALESCE(p.product_num, 0) AS product_num, o.total_amount, ROUND(o.total_amount / o.order_num, 2) AS avg_price, o.shop_id, 0 AS deleted FROM ( SELECT DATE(create_time) AS d, shop_id, COUNT(*) AS order_num, SUM(pay_amount) AS total_amount FROM lsc_order.order_info WHERE pay_status = 1 AND shop_id IS NOT NULL
AND DATE(create_time) = #{targetDate}
GROUP BY DATE(create_time), shop_id ) o LEFT JOIN ( SELECT DATE(o2.create_time) AS d, o2.shop_id, SUM(oi.quantity) AS product_num FROM lsc_order.order_info o2 JOIN lsc_order.order_item oi ON o2.id = oi.order_id WHERE o2.pay_status = 1 AND o2.shop_id IS NOT NULL
AND DATE(o2.create_time) = #{targetDate}
GROUP BY DATE(o2.create_time), o2.shop_id ) p ON o.d = p.d AND o.shop_id = p.shop_id ON DUPLICATE KEY UPDATE `order_num` = VALUES(`order_num`), `product_num` = VALUES(`product_num`), `price` = VALUES(`price`), `avg_price` = VALUES(`avg_price`), `deleted` = 0

mapper.select:
SELECT id, shop_id AS shopId, pay_amount AS payAmount, create_time AS createTime FROM lsc_order.order_info WHERE pay_status = 1 AND shop_id IS NOT NULL
AND DATE(create_time) = #{targetDate}
AND shop_id = #{shopId}
ORDER BY create_time ASC

SELECT oi.order_id AS orderId, o.shop_id AS shopId, oi.name AS name, COALESCE(oi.quantity, 1) AS quantity FROM lsc_order.order_item oi JOIN lsc_order.order_info o ON oi.order_id = o.id WHERE o.pay_status = 1 AND o.shop_id IS NOT NULL
AND DATE(o.create_time) = #{targetDate}
AND o.shop_id = #{shopId}

SELECT 
  id,
  shop_id AS shopId,
  pay_amount AS payAmount,
  create_time AS createTime
FROM lsc_order.order_info
WHERE pay_status = 1 AND shop_id = #{shopId}
  AND DATE(create_time) >= #{startDate}
  AND DATE(create_time) <= #{endDate}
ORDER BY create_time ASC
